import java.util.Random;

public class Solution01 {
    public static void main(String[] args) {
        // System.out.println(number); // 문법상 허용되지 않음 (변수가 선언되기 전에 사용 불가능)
        // Java는 변수 호이스팅(hoisting)을 지원하지 않음

        try {
            int number = 10;
            // JavaScript에서는 오류가 있어도 실행이 계속될 수 있지만, Java에서는 오류 발생 시 예외가 발생하여 프로그램이 종료됨
            // System.out.println(number / 0); // 0으로 나누는 연산 -> ArithmeticException 발생

            // throwRandom() 메서드 실행 -> 내부적으로 예외가 발생할 가능성이 있음
            System.out.println(throwRandom());

        } catch (Exception e) { // 모든 예외를 포괄적으로 처리할 수 있음
            e.printStackTrace(); // 발생한 예외의 스택 트레이스를 출력하여 디버깅할 수 있도록 함
        } finally {
            System.out.println("어쨌든 실행이 된다");
            // finally 블록은 예외 발생 여부와 관계없이 무조건 실행됨
        }

        System.out.println("도달할 수 있나?");
        // 예외가 발생하더라도 catch 블록에서 처리되었기 때문에 프로그램이 정상적으로 실행됨
    }

    static double throwRandom() { 
        // 클래스 메서드(static) -> 객체를 생성하지 않고 직접 호출 가능

        Random random = new Random();
        double result = random.nextDouble(); // 0.0 이상 1.0 미만의 난수를 생성

        try {
            if (result > 0.5) { 
                // result가 0.5보다 크면 예외를 강제로 발생시킴 (0으로 나누기)
                int error = 10 / 0;
            }
            return result; // 예외가 발생하지 않으면 result 값을 반환
        } catch (Exception e) {
            e.printStackTrace();
            result = -1; // 예외 발생 시 result 값을 -1로 설정
        } finally {
            if (result == -1) { 
                result = 9999; // 예외가 발생하면 result를 9999로 변경
            } else {
                result *= 1_000_000; // 예외가 발생하지 않으면 result를 100만 배 증가
            }
            return result; // finally 블록에서 값을 반환 -> try 또는 catch에서 설정한 return 값을 덮어씀
        }

        // return result; // 이 코드는 도달할 수 없음 (finally에서 return이 실행되므로)
    }
}
